module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        areset;
    reg        load;
    reg        ena;
    reg  [3:0] data;
    wire [3:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk    (clk),
        .areset (areset),
        .load   (load),
        .ena    (ena),
        .data   (data),
        .q      (q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    reg [3:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'b0000;
        expected_q = 4'b0000;

        // Test 1: Asynchronous Reset
        #3;
        areset = 1;
        #7;
        if (q !== 4'b0000) errors = errors + 1;

        areset = 0;
        #5;

        // Test 2: Synchronous Load
        @(posedge clk);
        #1;
        load = 1;
        data = 4'b1011;
        expected_q = 4'b1011;

        @(posedge clk);
        #1;
        load = 0;
        if (q !== expected_q) errors = errors + 1;

        // Test 3: Shift Right (ena = 1)
        // q is currently 4'b1011. Shift right -> 4'b0101
        ena = 1;
        expected_q = {1'b0, expected_q[3:1]}; // 4'b0101

        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Shift right again -> 4'b0010
        expected_q = {1'b0, expected_q[3:1]};
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 4: Priority Test (load and ena both high -> load wins)
        load = 1;
        data = 4'b1100;
        expected_q = 4'b1100;

        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Deassert load, keep ena high -> shift right -> 4'b0110
        load = 0;
        expected_q = {1'b0, expected_q[3:1]};
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 5: No operation (load=0, ena=0)
        ena = 0;
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1; // Should hold value

        // Test 6: Asynchronous reset during operation
        #2;
        areset = 1;
        expected_q = 4'b0000;
        #4;
        if (q !== expected_q) errors = errors + 1;
        areset = 0;

        // Final Result Display
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
